mapper.sql:
WHERE S.DEL_YN = 'N'

    AND S.SCHD_CLSF_CD IN

        #{cd}



    AND S.END_DT >= #{search.beginDt}


    AND S.BEGIN_DT <= #{search.endDt}


    AND (
        S.SCHD_NM LIKE '%' || #{search.keyword} || '%'
        OR E.EMP_NM LIKE '%' || #{search.keyword} || '%'
    )

mapper.select:
SELECT *
FROM (
    SELECT
        ,
        ROW_NUMBER() OVER (ORDER BY S.SCHD_REGST_DT DESC) AS RN


)
WHERE RN > #{offset}
  AND RN <= #{offset} + #{size}
